WITH WebEventsBySession AS (SELECT session_id, SUM(CASE WHEN event_type = 'page_view' THEN 1 ELSE 0 END) AS page_view_count, MIN(event_time) AS min_event_time FROM web_events WHERE event_time >= '2024-03-02' GROUP BY session_id) SELECT sessions.id, sessions.country, sessions.device, WebEventsBySession.page_view_count, WebEventsBySession.min_event_time FROM sessions LEFT JOIN WebEventsBySession ON sessions.id = WebEventsBySession.session_id;
